        /// <summary>
        /// Gets the decrypted service account JSON content
        /// </summary>
        public static string GetServiceAccountJson()
        {
            try
            {
                using var aes = Aes.Create();
                aes.Key = Key;
                aes.IV = IV;
                
                using var decryptor = aes.CreateDecryptor();
                var decryptedBytes = decryptor.TransformFinalBlock(EncryptedData, 0, EncryptedData.Length);
                
                return Encoding.UTF8.GetString(decryptedBytes);
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException("Failed to decrypt service account credentials", ex);
            }
        }

        /// <summary>
        /// Indicates whether compiled credentials are available
        /// </summary>
        public static bool HasCompiledCredentials => EncryptedData.Length > 0;
    }
